CustomCss:
body{letter-spacing:.1px}
h2{padding-bottom:8px;border-bottom:1px solid var(--b);letter-spacing:.6px}
.form,.sc,.ig,table{border-radius:10px}
.sc{background:linear-gradient(160deg,var(--s),transparent)}
.ni{border-radius:8px;transition:background .18s ease,color .18s ease}
.ni:hover{background:var(--hover);transform:translateX(2px)}
.ni.active{background:rgba(122,162,247,.12)}
.form:hover{border-color:var(--a)}
button.bp,button.bd,button.bw,button.bsm{border-radius:8px;font-weight:600;transition:transform .12s ease,box-shadow .12s ease}
button.bp:hover,button.bd:hover,button.bw:hover{transform:translateY(-1px)}
button.bp{box-shadow:0 1px 3px rgba(122,162,247,.3)}
input,select,textarea{border-radius:8px}
input:focus,select:focus,textarea:focus{box-shadow:0 0 0 3px rgba(122,162,247,.2)}
.code{text-shadow:0 0 8px rgba(122,162,247,.35)}
.pnl.active{animation:tnIn .25s ease}
@keyframes tnIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}
